string FindAfter(string rel,string expected)=>new[]{"main-missing-supplement-before","main-singleton-diagnostic-before","main-constructor-chain-before"}.Select(f=>Path.Combine(task,"work/recovery-stubs",f,rel)).Append(Path.Combine(project,rel)).FirstOrDefault(p=>File.Exists(p)&&Hash(p).Equals(expected,StringComparison.OrdinalIgnoreCase))??throw new Exception("Exact phase snapshot missing "+rel);
static string NormalizeAsm(string path)=>Regex.Replace(File.ReadAllText(path),@"(?m)^0x[0-9a-f]+: ","").Trim();
static BlockSyntax[] Bodies(SyntaxNode n)=>n.DescendantNodes().OfType<BlockSyntax>().Where(b=>b.Parent is BaseMethodDeclarationSyntax or AccessorDeclarationSyntax).ToArray();
static bool KnownStub(BlockSyntax b)=>b.Statements.Count==0||b.Statements.Count==1&&b.Statements[0] is ReturnStatementSyntax r&&r.Expression is not null&&(PureNull(r.Expression)||r.Expression.IsKind(SyntaxKind.DefaultLiteralExpression)||r.Expression is DefaultExpressionSyntax||r.Expression is RefExpressionSyntax rf&&rf.Expression is PrefixUnaryExpressionSyntax p&&p.IsKind(SyntaxKind.PointerIndirectionExpression)&&p.Operand is CastExpressionSyntax cast&&cast.Type is PointerTypeSyntax&&PureNull(cast.Expression));
static bool PureNull(ExpressionSyntax e)=>e.IsKind(SyntaxKind.NullLiteralExpression)||e is CastExpressionSyntax c&&PureNull(c.Expression)||e is CheckedExpressionSyntax ch&&PureNull(ch.Expression)||e is ParenthesizedExpressionSyntax p&&PureNull(p.Expression);
static uint SourceToken(MemberDeclarationSyntax n)=>Convert.ToUInt32(((LiteralExpressionSyntax)n.AttributeLists.SelectMany(x=>x.Attributes).Single(a=>a.Name.ToString()=="Token").ArgumentList!.Arguments[0].Expression).Token.ValueText[2..],16);
static uint OriginalToken(ICustomAttributeProvider n){var s=n.CustomAttributes.FirstOrDefault(a=>a.AttributeType.Name=="TokenAttribute")?.Fields.FirstOrDefault(f=>f.Name=="Token").Argument.Value as string;return s is null?0:Convert.ToUInt32(s[2..],16);}
static IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
static void CheckHash(string p,string hash){if(!Hash(p).Equals(hash,StringComparison.OrdinalIgnoreCase))throw new Exception("Hash mismatch "+p);}
